type S4I18nText = {
  ko: string;
  uz: string;
  en: string;
  ru: string;
};

type S4I18nOptions = {
  ko: string[];
  uz: string[];
  en: string[];
  ru: string[];
};

const S4_NATIVE_DISTRACTORS: S4I18nOptions = {
  ko: ['아니요', '하지만', '어제', '비싸요'],
  uz: ['yo‘q', 'lekin', 'kecha', 'qimmat'],
  en: ['not', 'but', 'yesterday', 'expensive'],
  ru: ['нет', 'но', 'вчера', 'дорого'],
};

function normalizeS4BuilderAnswer(value: string): string {
  return value
    .replace(/[.,!?;:…()"'“”«»]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeS4BuilderTranslations(value: S4I18nText): S4I18nText {
  return {
    ko: normalizeS4BuilderAnswer(value.ko),
    uz: normalizeS4BuilderAnswer(value.uz),
    en: normalizeS4BuilderAnswer(value.en),
    ru: normalizeS4BuilderAnswer(value.ru),
  };
}

function shuffledS4BuilderOptions(
  answer: string,
  distractors: string[],
): string[] {
  const words = normalizeS4BuilderAnswer(answer).split(' ').filter(Boolean);

  if (words.length < 2) {
    throw new Error(
      `Section 4 sentence_builder answer needs at least two words: ${answer}`,
    );
  }

  const extras = distractors
    .filter((word) => !words.includes(word))
    .slice(0, 2);

  const combined = [...words, ...extras];

  return [
    ...combined.filter((_, index) => index % 2 === 1),
    ...combined.filter((_, index) => index % 2 === 0),
  ];
}

function localizedS4BuilderOptions(answer: S4I18nText): S4I18nOptions {
  return {
    ko: shuffledS4BuilderOptions(answer.ko, S4_NATIVE_DISTRACTORS.ko),
    uz: shuffledS4BuilderOptions(answer.uz, S4_NATIVE_DISTRACTORS.uz),
    en: shuffledS4BuilderOptions(answer.en, S4_NATIVE_DISTRACTORS.en),
    ru: shuffledS4BuilderOptions(answer.ru, S4_NATIVE_DISTRACTORS.ru),
  };
}

function withS4SentenceBuilders<T extends Record<string, any>>(
  questions: T,
): T {
  return Object.fromEntries(
    Object.entries(questions).map(([code, question]) => {
      if (question.type !== 'sentence_builder') {
        return [code, question];
      }

      const answerI18n = normalizeS4BuilderTranslations(
        question.answerTranslation,
      );

      return [
        code,
        {
          ...question,
          instruction: I.listenNative,
          audioText: question.audioText || question.answer,
          answerI18n,
          optionsI18n: localizedS4BuilderOptions(answerI18n),
        },
      ];
    }),
  ) as T;
}

